const ARCHIVE_SKIP = Symbol("ARCHIVE_SKIP");

function parseArchiveLine(text, lineNumber) {
  if (text.trim() === "") {
    return ARCHIVE_SKIP;
  }

  try {
    return JSON.parse(text);
  } catch (error) {
    const syntaxError =
      error instanceof SyntaxError
        ? error
        : new SyntaxError(String(error && error.message ? error.message : error));

    syntaxError.code = "INVALID_RECORD";
    syntaxError.line = lineNumber;
    throw syntaxError;
  }
}

async function* readArchive(chunks) {
  const iterator = chunks[Symbol.asyncIterator]();
  let reachedEOF = false;
  let failed = false;

  try {
    const decoder = new TextDecoder("utf-8");
    let buffered = "";
    let lineNumber = 1;

    while (true) {
      const newlineIndex = buffered.indexOf("\n");

      if (newlineIndex !== -1) {
        const line = buffered.slice(0, newlineIndex);
        buffered = buffered.slice(newlineIndex + 1);

        const value = parseArchiveLine(line, lineNumber);
        lineNumber += 1;

        if (value !== ARCHIVE_SKIP) {
          yield value;
        }

        continue;
      }

      if (reachedEOF) {
        if (buffered !== "") {
          const value = parseArchiveLine(buffered, lineNumber);
          buffered = "";

          if (value !== ARCHIVE_SKIP) {
            yield value;
          }
        }

        return;
      }

      const result = await iterator.next();

      if (result.done) {
        reachedEOF = true;
        buffered += decoder.decode();
      } else {
        buffered += decoder.decode(result.value, { stream: true });
      }
    }
  } catch (error) {
    failed = true;
    throw error;
  } finally {
    if (!reachedEOF) {
      if (failed) {
        try {
          const returnMethod = iterator.return;
          if (typeof returnMethod === "function") {
            await returnMethod.call(iterator);
          }
        } catch {
          // Preserve the original processing or source error.
        }
      } else {
        const returnMethod = iterator.return;
        if (typeof returnMethod === "function") {
          await returnMethod.call(iterator);
        }
      }
    }
  }
}
